def membership_for_primary_team(apps, schema_editor):
    """Every live person with a (live) primary team becomes a member of it (CR-32)."""
    Person = apps.get_model("masterdata", "Person")
    TeamMembership = apps.get_model("masterdata", "TeamMembership")
    pairs = Person.objects.filter(
        is_deleted=False, team__isnull=False, team__is_deleted=False
    ).values_list("team_id", "id")
    batch = []
    for team_id, person_id in pairs.iterator(chunk_size=1000):
        batch.append(TeamMembership(team_id=team_id, person_id=person_id))
        if len(batch) >= 1000:
            TeamMembership.objects.bulk_create(batch, ignore_conflicts=True)
            batch = []
    if batch:
        TeamMembership.objects.bulk_create(batch, ignore_conflicts=True)


